'use strict';
const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const writeStore=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器无法保存数据，请导出文件备份');return false}};
let saved=readStore('rwlab-saved',[]), completed=readStore('rwlab-completed',[]), query='',category='全部代码',order='default',refGroup='fields',refScope='',refQuery='',refEvidence='',refPage=1,refData=[],manualData=null;
const cache={}, main=$('#main'), categories=['全部代码','单位基础','武器系统','动作逻辑','建筑经济','地图触发','图像动画','模组配置'];
const paths={tank:'M3 8h18v9H3z M6 5v3m12-3v3M8 11h8v4H8z M12 11V3',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z M8 12l3 3 5-6',crosshair:'M12 2v5m0 10v5M2 12h5m10 0h5 M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0',radar:'M12 12l7-7 M21 12a9 9 0 1 1-9-9 M16 12a4 4 0 1 1-4-4',building:'M4 21V9l8-6 8 6v12M8 21v-6h8v6M8 10h2m4 0h2',factory:'M3 21V8l6 4V8l6 4V3h5v18zM7 17h2m4 0h2',bolt:'M13 2 4 14h7l-1 8 10-13h-7z',energy:'M13 2 4 14h7l-1 8 10-13h-7z',layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 17l10 5 10-5',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h8',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'};
function icon(name,cls='category-icon'){return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
function toast(message){message=RWI18n.t(message);const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function blank(title,description,button=''){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(description)}</p>${button}</div>`}
function tankDrawing(isHero=false){return `<g transform="translate(${isHero?'250 148':'150 63'}) rotate(-32) scale(${isHero?'1.12':'.61'})"><ellipse cy="12" rx="91" ry="54" fill="${isHero?'#152018':'#768466'}" opacity=".15"/><g fill="${isHero?'#4d6144':'#8c9c74'}" stroke="${isHero?'#8d9d70':'#607451'}" stroke-width="1.2"><path d="M-61-50h24v105h-24zM37-50h24v105H37z"/><path d="M-52-51h10v108h-10M44-51h10v108H44" fill="none"/>${Array.from({length:11},(_,i)=>`<path d="M-61 ${-45+i*9}h24M37 ${-45+i*9}h24" stroke-opacity=".65"/>`).join('')}<path d="m-37-52 74 0 7 15v74L30 54h-59L-44 37v-74z" fill="${isHero?'#78835a':'#a7b38b'}"/><path d="M-29-41H29L35-29v57l-9 14h-52l-9-14v-57z" fill="${isHero?'#899068':'#bbc5a6'}"/><path d="M-29 22h58v12h-58z" fill="${isHero?'#4b5b40':'#7d9066'}"/><path d="M-23 25h46m-46 4h46" stroke-opacity=".5"/><path d="m-26-18 13-14h26l14 14v32L12 27h-24L-26 14z" fill="${isHero?'#909571':'#9dad80'}"/><path d="m-20-14 10-11h21l10 11v23L9 20h-18L-20 9z" fill="${isHero?'#6a7952':'#c0c9a6'}"/><circle r="10" fill="${isHero?'#9ca07a':'#9dae81'}"/><path d="M-5-6v-70H5v70z" fill="${isHero?'#a9aa83':'#7d9264'}"/><path d="M-7-83H7v12H-7z" fill="${isHero?'#6c7b53':'#9eae80'}"/><path d="M-32-40h14v10h-14M18-40h14v10H18" fill="${isHero?'#a2a37b':'#c5ceb2'}"/><path d="m-10 36 10-6 10 6-10 5z" fill="${isHero?'#cfad73':'#d18a58'}" stroke="none"/></g></g>`}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><div class="art-top"><span>UNIT BLUEPRINT / RW-01</span><span>TACTICAL VIEW +</span></div><i class="art-corner a"></i><svg class="tank-scene" viewBox="0 0 520 320"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="#b0bc8c" opacity=".18"/></pattern></defs><rect width="520" height="320" fill="url(#dots)"/><g fill="none" stroke="#7d8e68" opacity=".24"><path d="M0 70c60-60 100 10 170-40S300-30 370 8s80 8 150-4M0 83c60-60 100 10 170-40S300-17 370 21s80 8 150-4M0 96c60-60 100 10 170-40S300-4 370 34s80 8 150-4M0 245c60-30 70 50 140 20s110-10 150 30 130-30 230-20M0 259c60-30 70 50 140 20s110-10 150 30 130-30 230-20"/><circle cx="250" cy="148" r="127" stroke-dasharray="3 7"/><circle cx="250" cy="148" r="104"/><path d="M95 148h310M250 0v296" stroke-dasharray="4 6"/></g><path d="m80 205 36-46m-11 0h11v11M400 80l35-25h24" fill="none" stroke="#ba9d67" opacity=".6"/><g font-family="monospace" font-size="7" fill="#839575"><text x="384" y="47">RANGE: 150</text><text x="35" y="218">LAND UNIT</text><text x="35" y="230">HP: 220 / 220</text><text x="135" y="40">X: 024 / Y: 148</text></g><circle cx="116" cy="159" r="3" fill="#c49d64"/>${tankDrawing(true)}<path d="m321 58 15-15 22 9-15 15z" fill="#7a8e5c" opacity=".4"/><path d="m110 103-11-8-7 12 10 7z" fill="#7a8e5c" opacity=".35"/></svg><div class="floating-code"><div class="filename">● ● ● &nbsp; units/scout.ini</div><pre><b>[core]</b>\nname: rwDocScout\nmaxHp: <b>220</b>\n\n<b>[turret_main]</b>\nprojectile: shell\naltProjectileCondition: <b>memory.powered</b></pre></div><div class="art-caption"><span><strong>01</strong> SCOUT PROTOTYPE</span><span>ILLUSTRATIVE BLUEPRINT</span></div><i class="art-corner b"></i></div>`}
function cardArt(s,index){const mode=s.category==='武器系统'?'weapon':s.category==='动作逻辑'?'action':s.category==='建筑经济'?'building':'';let illustration;if(s.icon==='tank')illustration=tankDrawing();else if(s.icon==='crosshair')illustration=`<g stroke="#9c8059" fill="none" stroke-width="1.4"><circle cx="150" cy="61" r="37"/><circle cx="150" cy="61" r="25" stroke-dasharray="3 4"/><circle cx="150" cy="61" r="9" fill="#b99b6c66"/><path d="M150 16v20m0 50v20M105 61h20m50 0h20M131 80l-26 22m65-60 25-25"/><path d="m144 60 9-14 9 14-9 14z" fill="#a38e67"/></g>`;else if(s.icon==='radar')illustration=`<g fill="none" stroke="#6f896c"><circle cx="150" cy="64" r="43"/><circle cx="150" cy="64" r="28"/><circle cx="150" cy="64" r="13"/><path d="M150 17v94m-48-47h96M150 64l35-32"/><path d="m150 64 35-32a44 44 0 0 1 8 34z" fill="#7c986b44"/><circle cx="176" cy="52" r="3" fill="#c68650"/></g>`;else if(s.icon==='building')illustration=`<g fill="#b1b79b" stroke="#718362" stroke-width="1.2"><path d="m108 50 41-23 43 24-41 24z"/><path d="M108 50v40l43 24V75z" fill="#96a282"/><path d="m151 75 41-24v39l-41 24z" fill="#7f926f"/><path d="m129 49 20-11 20 11-20 12z" fill="#d5d6bc"/><path d="M149 38V17M132 83v15m8-10v15m22-14 19-11v11l-19 11z"/></g>`;else illustration=`<g fill="none" stroke="#7d9271" stroke-width="1.2"><path d="m150 25 55 30-55 31-55-31z" fill="#b1bea160"/><path d="m95 65 55 31 55-31M95 77l55 31 55-31"/><path d="m139 48-11 7 11 7m22-14 11 7-11 7m-7-20-8 28" stroke="#59784d" stroke-width="2"/></g>`;return `<div class="card-art ${mode}"><span class="art-id">RW LAB / ${String(index+1).padStart(3,'0')}</span><svg viewBox="0 0 300 127" aria-hidden="true">${illustration}</svg><span class="art-type">${esc(s.category==='地图触发'?'TMX FRAGMENT':'CONFIG BLUEPRINT')}</span></div>`}
function card(s){const idx=SNIPPETS.indexOf(s);return `<article class="code-card"><button class="bookmark ${saved.includes(s.id)?'is-saved':''}" data-action="bookmark" data-id="${s.id}" aria-label="${saved.includes(s.id)?'取消收藏':'收藏'}：${esc(s.title)}" aria-pressed="${saved.includes(s.id)}">${saved.includes(s.id)?'★':'☆'}</button>${cardArt(s,idx)}<div class="card-body"><div class="card-badges"><span class="tag">${esc(s.category)}</span><span class="tag level">${s.level}</span></div><h3 class="card-title"><a href="#code/${s.id}">${esc(s.title)}</a></h3><p class="card-description">${esc(s.description)}</p><div class="card-footer"><span>⌘ ${esc(s.file.endsWith('xml')?'XML / TMX':'INI / 1.15')}</span><span>适用于 1.15</span></div></div></article>`}
function sectionHeading(en,title,desc='',link=''){return `<div class="section-heading"><div><div class="eyebrow">${en}</div><h2>${title}</h2>${desc?`<p class="heading-sub">${desc}</p>`:''}</div>${link}</div>`}
function categoryButtons(){return categories.map((c,i)=>`<button class="category ${category===c?'active':''}" data-action="category" data-category="${c}"><span>${icon(['layers','tank','crosshair','bolt','building','radar','layers','file'][i])}${c}</span><small>${i===0?SNIPPETS.length:SNIPPETS.filter(s=>s.category===c).length}</small></button>`).join('')}
function libraryShell(home=false,onlySaved=false){return `<div class="library-layout"><aside class="sidebar"><div class="side-label">BROWSE BY CATEGORY</div><div class="categories">${categoryButtons()}</div><div class="side-box"><span>↗</span><h3>第一次编写模组？</h3><p>跟着完整注释示例，理解一个单位如何进入战场。</p><a href="#learn/start">从第一课开始 →</a></div><div class="side-box"><span>↓</span><h3>资料包已完整收录</h3><p>原手册、JSON 索引、示例与验证记录，随时查阅。</p><a href="#downloads">打开资料下载站 →</a></div></aside><section aria-label="代码列表"><div class="library-tools"><label class="search-box">${icon('search')}<input type="search" id="code-search" value="${esc(query)}" placeholder="搜索代码、功能或参数名称…" aria-label="搜索代码"><kbd>/</kbd></label><select id="code-sort" class="sort" aria-label="代码排序"><option value="default" ${order==='default'?'selected':''}>收录顺序</option><option value="beginner" ${order==='beginner'?'selected':''}>入门优先</option><option value="name" ${order==='name'?'selected':''}>名称排序</option></select></div><div class="filter-info"><span id="code-result-count"></span><span>ANNOTATED / RW 1.15</span></div><div class="cards" id="code-cards" data-home="${home}" data-saved="${onlySaved}"></div><div id="code-more"></div><p class="evidence-note">完整示例可以直接下载；代码片段请按说明添加到对应文件。<a href="#about">了解证据等级 ↗</a></p></section></div>`}
function updateCards(){const box=$('#code-cards');if(!box)return;const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean);let items=SNIPPETS.filter(s=>(category==='全部代码'||s.category===category)&&(box.dataset.saved!=='true'||saved.includes(s.id))&&words.every(w=>(s.title+s.description+s.tags.join(' ')+s.code).toLowerCase().includes(w)));if(order==='beginner')items.sort((a,b)=>a.level.localeCompare(b.level,'zh-CN'));if(order==='name')items.sort((a,b)=>a.title.localeCompare(b.title,'zh-CN'));$('#code-result-count').textContent=`找到 ${items.length} 段代码${category!=='全部代码'?' / '+category:''}`;const limit=box.dataset.home==='true'&&!query&&category==='全部代码'?6:items.length;box.innerHTML=items.slice(0,limit).map(card).join('')||blank(box.dataset.saved==='true'?'收藏夹还没有匹配内容':'没有找到匹配代码','试试“内存”“炮塔”或清除筛选。','<button class="btn btn-plain" data-action="reset-search">清除筛选</button>');$('#code-more').innerHTML=items.length>limit?'<div class="library-bottom"><a class="btn btn-plain" href="#library">查看全部代码 <span>↓</span></a></div>':'';document.querySelectorAll('.category').forEach(b=>b.classList.toggle('active',b.dataset.category===category))}
function lessonRow(l){return `<a class="lesson-row" href="#learn/${l.id}"><span class="lesson-number">${l.number}</span><div><h3>${esc(l.title)}</h3><p>${l.level} · ${l.time}${completed.includes(l.id)?' · 已完成':''}</p></div><span class="row-arrow">↗</span></a>`}
function homePage(){main.innerHTML=`<section class="hero"><div class="hero-inner"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> RUSTED WARFARE · CREATOR'S WORKSHOP</div><h1>把想象，<br>写进<span><em>战场</em>。</span></h1><p>一段配置，一种新可能。<br>探索铁锈战争的模组语言，在代码与教程中构建你的下一场战役。</p><div class="hero-cta"><a href="#library" class="btn btn-orange">探索代码仓库 <span>↗</span></a><a href="#learn/start" class="btn btn-outline">开始编写模组 <span>→</span></a></div><div class="hero-note"><span>⌘</span><code>INI + LOGIC + TMX</code><span>·</span><span>适用于铁锈战争 1.15</span></div></div>${heroArt()}</div></section><div class="stats-strip"><div class="stats-inner"><div class="stat"><strong>984</strong><span>配置项索引</span></div><i class="stat-divider"></i><div class="stat"><strong>143</strong><span>逻辑名称与别名</span></div><i class="stat-divider"></i><div class="stat"><strong>88</strong><span>地图解析属性</span></div><i class="stat-divider"></i><div class="stat"><strong>08</strong><span>循序渐进的教程</span></div><div class="stats-version"><i class="tiny-square"></i> REFERENCE / ANDROID 1.15</div></div></div><section class="section-wrap">${sectionHeading('EXPLORE THE CODEBASE','从一段代码，开始创造。','看看别人是怎么实现的，再把学到的方法用到自己的模组里。','<a class="text-link" href="#reference">查阅完整参数 <span>↗</span></a>')}${libraryShell(true)}</section><section class="section-wrap course-section">${sectionHeading('LEARN. BUILD. ITERATE.','每一次尝试，都离新模组更近。','跟着侦察车示例，逐步学会导入模组、添加武器和编排动作。','<a class="text-link" href="#tutorials">全部 8 课 <span>↗</span></a>')}<div class="course-grid"><a class="course-feature" href="#learn/start"><span class="eyebrow">START YOUR FIRST MOD</span><h3>第一个模组，<br>从这里开始。</h3><p>下载完整中文注释示例，读懂一个单位如何运行。</p><span class="text-link">进入第一课 <span>→</span></span></a><div class="course-stack">${lessonRow(LESSONS[1])}${lessonRow(LESSONS[2])}</div><div class="course-stack">${lessonRow(LESSONS[3])}${lessonRow(LESSONS[6])}</div></div><div class="bottom-banner"><div><h3>手册很厚，查找可以很轻。</h3><p>18 章中文手册、完整 JSON 索引与原始示例，已整合进这个工坊。</p></div><a class="btn btn-dark" href="#downloads">打开资料库 <span>↗</span></a></div></section>`;updateCards()}
function heading(en,title,description,bread=''){return `<div class="page-head">${bread?`<div class="breadcrumb"><a href="#home">工坊首页</a><span>/</span>${bread}</div>`:''}<div class="eyebrow">${en}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>`}
function libraryPage(onlySaved=false){main.innerHTML=heading(onlySaved?'YOUR FIELD NOTES':'THE CODE REPOSITORY',onlySaved?'我的代码收藏':'代码仓库',onlySaved?'收藏保存在当前浏览器，便于下次接着研究。':'9 个完整示例和实用片段，帮你了解单位、武器、动作和地图事件的写法。')+`<div class="section-wrap" style="padding-top:5px">${libraryShell(false,onlySaved)}</div>`;updateCards()}
function codePanel(code,file,actions=true){return `<div class="code-panel"><div class="code-panel-head"><span>● ● ● &nbsp; ${esc(file)}</span>${actions?'<div><button class="code-button" data-action="copy-code">复制代码 ⧉</button><button class="code-button" data-action="download-code">下载 ↓</button></div>':''}</div><pre><code>${code.split('\n').map((line,i)=>{let v=esc(line);if(line.trim().startsWith('#')||line.trim().startsWith('<!--'))v=`<span class="syntax-comment">${v}</span>`;else if(/^\s*\[/.test(line))v=`<span class="syntax-section">${v}</span>`;else if(line.includes(':')){const n=line.indexOf(':');v=`<span class="syntax-key">${esc(line.slice(0,n))}</span>:<span class="syntax-value">${esc(line.slice(n+1))}</span>`}return `<span class="code-line"><span class="line-no" aria-hidden="true">${i+1}</span>${v}</span>`}).join('')}</code></pre></div>`}
let currentCode=null;
function codePage(id){const s=SNIPPETS.find(x=>x.id===id);if(!s){notFound();return}currentCode=s;main.innerHTML=heading('CODE / '+String(SNIPPETS.indexOf(s)+1).padStart(3,'0'),s.title,s.description,`<a href="#library">代码仓库</a><span>/</span><span>${esc(s.category)}</span>`)+`<div class="article-layout"><aside class="article-toc"><div class="side-label">IN THIS SNIPPET</div><a href="#code/${s.id}">配置与依赖</a><a href="#learn/${s.id==='map'?'maps':s.id==='resource'?'resources':s.id==='counter'||s.id==='toggle'?'memory':s.id==='inherit'||s.id==='animation'?'templates':'start'}">配套教程 →</a><a href="#reference">参数与来源 →</a><a href="#downloads">原始资料下载 →</a></aside><article class="article-main"><div class="detail-meta"><span class="tag">${esc(s.category)}</span><span class="tag level">${s.level}</span><span>${esc(s.origin)}</span></div><div class="callout warning"><strong>接入前先读</strong><br>${esc(s.note)}</div>${codePanel(s.code,s.file)}<div class="detail-actions"><button class="btn btn-orange" data-action="copy-code">复制完整代码 ⧉</button><button class="btn btn-plain" data-action="download-code">下载 ${s.file.endsWith('xml')?'XML':'文件'} ↓</button><button class="btn btn-plain" data-action="bookmark" data-id="${s.id}">${saved.includes(s.id)?'★ 已收藏':'☆ 收藏代码'}</button><button class="btn btn-plain" data-action="share-link">分享链接 ↗</button></div>${s.download?`<div class="callout">需要直接导入的文件？<a href="${s.download}" download><strong>下载资料包原始 Annotated_Scout.rwmod ↓</strong></a><br>原始 README、mod-info.txt 与 scout.ini 一并包含；共享图片由目标游戏包提供。</div>`:''}<h2>如何验证这段代码？</h2><p>先读依赖说明，将片段合入完整文件，检查变量和引用名。再在目标游戏版本中重新加载，观察对应行为并记录报错。原资料包已完成静态检查；本站未启动游戏验证。</p><p>参考资料：Rusted Warfare 1.15 Mod Reference Pack。<a class="text-link" href="#about">查看证据与验证范围 ↗</a></p><div class="article-nav"><a href="#library">← 返回代码仓库</a><a href="#tutorials">继续学习教程 →</a></div></article></div>`}
function tutorialsPage(){main.innerHTML=heading('THE LEARNING PATH','从导入示例，到独立创造。','从一个完整示例开始，分 8 课学习单位、武器、动作和地图事件。每课都有可以动手尝试的小练习。')+`<div class="section-wrap" style="padding-top:5px"><div class="tutorial-grid">${LESSONS.map(l=>`<a class="tutorial-card" href="#learn/${l.id}"><span class="lesson-number">${l.number}</span>${completed.includes(l.id)?'<span class="done">✓ 已完成</span>':''}<h2>${esc(l.title)}</h2><p>${esc(l.description)}</p><span>${l.level} · ${l.time} &nbsp; →</span></a>`).join('')}</div><div class="callout">教程学习进度保存在当前浏览器。完整字段细节请结合<a href="#reference"><strong>参数速查</strong></a>与<a href="#manual"><strong>原手册</strong></a>阅读。</div></div>`}
function lessonPage(id){const i=LESSONS.findIndex(l=>l.id===id),l=LESSONS[i];if(!l){notFound();return}main.innerHTML=heading('LESSON '+l.number+' / 08',l.title,l.description,'<a href="#tutorials">模组教程</a><span>/</span><span>第 '+l.number+' 课</span>')+`<div class="article-layout"><aside class="article-toc"><div class="side-label">LEARNING PATH</div>${LESSONS.map(x=>`<a href="#learn/${x.id}" ${x.id===id?'aria-current="page" style="color:var(--orange)"':''}>${x.number} ${esc(x.title)}</a>`).join('')}</aside><article class="article-main"><div class="detail-meta"><span class="tag level">${l.level}</span><span>阅读约 ${l.time}</span><span>目标资料：Android 1.15</span></div>${id==='start'?'<div class="detail-actions"><a class="btn btn-orange" href="downloads/examples/Annotated_Scout.rwmod" download>下载注释侦察车 .rwmod ↓</a><a class="btn btn-plain" href="#code/scout">阅读完整源文件 →</a></div>':''}${l.sections.map((s,j)=>`<section><h2><span class="small-mono">${String(j+1).padStart(2,'0')} / </span>${esc(s[0])}</h2><p>${esc(s[1])}</p>${s[2]?codePanel(s[2],'教学片段 · 阅读前核对所属文件与段落',false):''}</section>`).join('')}<div class="detail-actions"><button class="btn ${completed.includes(id)?'completed':'btn-dark'}" data-action="complete-lesson" data-id="${id}">${completed.includes(id)?'✓ 已标记完成':'✓ 标记本课完成'}</button><a class="btn btn-plain" href="#reference">打开参数速查 ↗</a></div><div class="article-nav">${i>0?`<a href="#learn/${LESSONS[i-1].id}">← 上一课</a>`:'<a href="#tutorials">← 全部教程</a>'}${i<LESSONS.length-1?`<a href="#learn/${LESSONS[i+1].id}">下一课：${esc(LESSONS[i+1].title)} →</a>`:'<a href="#library">去代码仓库试试 →</a>'}</div></article></div>`}
const refGroups={fields:['配置字段','unit_fields.json'],logic:['逻辑与引用','logic_functions.json'],map:['地图属性','map_properties.json'],stats:['可修改属性','mutable_stats.json'],syntax:['专用小语法','mini_languages.json'],patterns:['动态键与旧式','dynamic_key_patterns.json'],builtins:['内置名称','builtin_names.json']};
function normalizeReference(group,raw){if(group==='logic')return raw.map(r=>({...r,key:r.names.join(' / '),scope:'LogicBoolean',type:r.return_type,description_zh:r.description_zh}));if(group==='map')return raw;if(group==='fields')return raw.map(r=>({...r,scope:r.section}));if(group==='stats')return raw.map(r=>({...r,scope:'setUnitStats',type:(r.operators||[]).join(' '),evidence:'B'}));return Object.entries(raw).flatMap(([scope,rows])=>scope.endsWith('_note_zh')?[{key:'builtin_effects',scope:'Notes',description_zh:rows}]:(Array.isArray(rows)?rows:[rows]).map(r=>typeof r==='string'?{key:r,scope,description_zh:'参见资料包原始索引'}:{...r,key:r.key||r.name||scope,scope,type:r.display_type||r.type||'',description_zh:r.description_zh||r.note_zh||r.range||'详见原始条目'}))}
async function referencePage(){main.innerHTML=heading('REFERENCE / SOURCE-TRACEABLE','查参数，找写法。','搜索参数名或想实现的功能，查看解释、可用值和示例。')+`<div class="section-wrap" style="padding-top:4px"><div class="reference-tabs">${Object.entries(refGroups).map(([k,v])=>`<button data-action="ref-group" data-group="${k}" class="${k===refGroup?'active':''}">${v[0]}</button>`).join('')}</div><div class="reference-toolbar"><label class="search-box">${icon('search')}<input type="search" id="ref-search" aria-label="搜索参考条目" value="${esc(refQuery)}" placeholder="输入参数名、功能或类型，例如 setUnitMemory、时间、炮塔…"><kbd>/</kbd></label><select class="sort" id="ref-scope" aria-label="按所属节筛选"><option value="">全部所属节</option></select><select class="sort" id="ref-evidence" aria-label="按证据等级筛选"><option value="">全部证据</option><option value="A" ${refEvidence==='A'?'selected':''}>A · 资产与解析</option><option value="B" ${refEvidence==='B'?'selected':''}>B · 解析/注册</option></select></div><div class="filter-info"><span id="ref-result-count"></span><a href="reference/${refGroups[refGroup][1]}" download>原始 JSON ↓</a></div><div id="reference-results"><div class="loader">正在读取资料包索引…</div></div><p class="evidence-note">参数适用于 Android 1.15。修改后请在游戏中测试；需要进一步核对时，可以展开条目查看原始参考记录。</p></div>`;const group=refGroup;try{const raw=cache[group]||await fetch('reference/'+refGroups[group][1]).then(r=>{if(!r.ok)throw Error();return r.json()});cache[group]=raw;if(group!==refGroup||!$('#ref-scope'))return;refData=normalizeReference(group,RWI18n.reference(group,raw));const scopes=[...new Set(refData.map(r=>r.scope||''))].sort();$('#ref-scope').innerHTML='<option value="">全部所属节</option>'+scopes.filter(Boolean).map(s=>`<option ${s===refScope?'selected':''} value="${esc(s)}">${esc(s)}</option>`).join('');if(!scopes.includes(refScope))refScope='';updateReference()}catch{$('#reference-results').innerHTML=blank('索引暂时未能加载','请刷新页面重试，或从资料下载页获取完整资料包。','<a class="btn btn-plain" href="#downloads">下载资料包</a>')}}
function updateReference(){const output=$('#reference-results');if(!output)return;const words=refQuery.trim().toLowerCase().split(/\s+/).filter(Boolean);const rows=refData.filter(r=>(!refScope||r.scope===refScope)&&(!refEvidence||r.evidence===refEvidence)&&words.every(w=>JSON.stringify(r).toLowerCase().includes(w)));const pages=Math.max(1,Math.ceil(rows.length/25));refPage=Math.min(Math.max(1,refPage),pages);$('#ref-result-count').textContent=`共 ${rows.length} 条 / 本类 ${refData.length} 条`;output.innerHTML=rows.length?`<table class="reference-table"><thead><tr><th>字段 / 所属节</th><th>类型 / 证据</th><th>中文说明 · 展开查看完整条目</th></tr></thead><tbody>${rows.slice((refPage-1)*25,refPage*25).map(r=>`<tr><td>${esc(r.key)}<span class="ref-scope">${esc(r.scope)}</span></td><td><span>${esc(r.type||'—')}</span>${r.evidence?`<br><span class="ref-evidence ${r.evidence==='B'?'b':''}">${esc(r.evidence)}</span>`:''}</td><td><details><summary>${esc(r.description_zh||'查看原始条目')}</summary><div class="ref-details">${r.default_behavior_zh?'缺省：'+esc(r.default_behavior_zh)+'<br>':''}${r.note_zh?'备注：'+esc(r.note_zh)+'<br>':''}${r.asset_example?'包内示例：'+esc(r.asset_example.value)+'<br>':''}<strong>完整原始记录</strong><pre>${esc(JSON.stringify(r,null,2))}</pre></div></details></td></tr>`).join('')}</tbody></table><div class="pagination"><button class="btn btn-plain btn-small" data-action="ref-prev" ${refPage<=1?'disabled':''}>← 上一页</button><span>${refPage} / ${pages}</span><button class="btn btn-plain btn-small" data-action="ref-next" ${refPage>=pages?'disabled':''}>下一页 →</button></div>`:blank('没有找到匹配条目','换一个关键词，或清除所属节与证据筛选。','<button class="btn btn-plain" data-action="ref-reset">清除筛选</button>')}
async function manualPage(index=0){main.innerHTML=heading('THE COMPLETE HANDBOOK','18 章原始中文手册','保留参考资料包中的原文，教程之外的细节、限制与索引均可继续查阅。')+'<div class="section-wrap" id="manual-content" style="padding-top:5px"><div class="loader">正在读取手册…</div></div>';try{manualData=manualData||await fetch('reference/manual-chapters.json').then(r=>{if(!r.ok)throw Error();return r.json()});if(!$('#manual-content'))return;index=Math.min(Math.max(Number(index)||0,0),manualData.length-1);$('#manual-content').innerHTML=`<div class="manual-chapters">${manualData.map((c,i)=>`<a href="#manual/${i}" class="${i===index?'active':''}">${esc(c.title)}</a>`).join('')}</div><div class="detail-actions"><a class="btn btn-plain" href="downloads/manual.txt" download>下载完整手册 TXT ↓</a><a class="btn btn-plain" href="#reference">切换到可搜索索引 ↗</a></div><div class="callout">原资料整理于 2026-10-17，范围为指定 Android 1.15 包。以下内容为原文；验证说明与来源限定保持不变。</div><div class="manual-body" data-no-translate>${esc(manualData[index].body)}</div>`}catch{$('#manual-content').innerHTML=blank('手册暂时未能加载','你仍可以直接下载 TXT 原文。','<a class="btn btn-plain" href="downloads/manual.txt" download>下载手册</a>')}}
function downloadsPage(){const docs=[['FULL REFERENCE / ZIP','完整参考资料包','原始手册、JSON、示例、校验报告与只读检索脚本。','downloads/reference-pack.zip','下载完整 ZIP'],['ANNOTATED SCOUT / RWMOD','中文注释侦察车','资料包原始 Mod：弹种切换与射击计数，已静态检查。','downloads/examples/Annotated_Scout.rwmod','下载 .rwmod'],['HANDBOOK / UTF-8 TXT','中文注释手册','18 章完整原文，包含语法、证据边界与附录。','downloads/manual.txt','下载手册'],['QUICK INDEX / TXT','字段速查索引','适合编辑器内快速搜索的离线字段索引。','downloads/field-index.txt','下载索引'],['RESOURCE & MEMORY / INI','资源与内存片段','原始片段，需合入完整单位并初始化内存。','downloads/examples/resource_memory_fragment.ini.txt','下载片段'],['MAP TRIGGER / XML','地图增援触发器','原始 TMX 对象组片段，不是独立可玩地图。','downloads/examples/map_trigger_fragment.xml','下载片段'],['VALIDATION / JSON','验证记录','保留资料包的检查项目、结果与未实机运行说明。','reference/verification_report.json','下载记录'],['PROVENANCE / JSON','输入包指纹','原分析输入包的来源指纹与目录统计。','reference/package_manifest.json','下载清单'],['SOURCE / INI','侦察车完整配置源文件','逐行中文注释，便于在编辑器中对照修改。','downloads/examples/Annotated_Scout/units/scout.ini','下载 scout.ini']];main.innerHTML=heading('THE RESOURCE DEPOT','把整座工坊，放进口袋。','下载 1.15 参考资料、完整示例和常用代码，离线也能继续学习。')+`<div class="section-wrap" style="padding-top:5px"><div class="download-grid">${docs.map(d=>`<a class="download-card" href="${d[3]}" download><div class="eyebrow">${d[0]}</div><h3>${d[1]}</h3><p>${d[2]}</p><span>${d[4]} ↓</span></a>`).join('')}</div><div class="callout warning">示例和参考资料适用于 Android 1.15。使用前请阅读接入说明，并在游戏中测试修改后的效果。</div><a class="text-link" href="#manual">直接在线阅读原手册 →</a></div>`}
function aboutPage(){const en=RWI18n.lang==='en',sections=[["在这里做什么","铁锈战争模组工坊是一个独立的铁锈战争模组创作站。你可以跟着教程学习、从代码示例中找思路，也可以直接使用单位编辑器和地图触发器编辑器。","Make something for Rusted Warfare","Rusted Workshop is an independent modding site. Learn with step-by-step tutorials, explore code examples, or build a unit or map event in the editors."],["参考资料","参数和教程主要参考 Rusted Warfare 1.15 Mod Reference Pack，适用范围为 Android 1.15。原始中文手册和示例完整保留，英文版提供翻译后的教程、界面和参数说明。","Reference material","The guides and settings are based on the Rusted Warfare 1.15 Mod Reference Pack for Android 1.15. The English site includes translated tutorials, interfaces and parameter descriptions. The original handbook and example source files remain in Chinese."],["保存与导出","收藏、学习进度和编辑器草稿保存在当前浏览器，不会自动发布。请定期导出项目备份；清理浏览器数据会清除这些记录。地图图片编辑器负责贴图与地块拼接，地图触发器负责事件；复杂地图可以继续使用 Tiled。","Saving and exporting","Bookmarks, lesson progress and editor drafts are stored in this browser and are not published automatically. Export projects for backup. Clearing browser data removes these records. The map image editor draws textures and tile layouts, while the trigger editor handles events; Tiled remains useful for complex maps."],["使用前先试一试","代码检查可以帮助发现常见问题，但不能代替游戏测试。导入模组后，请确认图像、武器、动作和地图事件是否按预期工作。分享作品时，写清所需版本、素材和测试情况。","Try your work in game","Code checks help find common mistakes but do not replace testing in the game. Check the graphics, weapons, actions and map events after importing. When sharing a mod, include its game version, assets and test results."],["图标、作品与许可","本站与 Corroding Games 无隶属关系。游戏图标版权归 Corroding Games 所有。示例保留原作者和来源说明；分享他人作品前，请先确认授权。","Credits and permissions","This site is not affiliated with Corroding Games. The game icon belongs to Corroding Games. Examples retain their source credits. Check permission before sharing another author’s work."]];main.innerHTML=heading('ABOUT THE WORKSHOP',en?'A place to learn, build and share.':'一起学习，把想法做成模组。',en?'A community workbench for Rusted Warfare creators.':'给铁锈战争创作者准备的教程、代码和工具。')+`<article class="section-wrap page-narrow about-body" style="padding-top:0">${sections.map(x=>'<h2>'+esc(x[en?2:0])+'</h2><p>'+esc(x[en?3:1])+'</p>').join('')}<p><a href="https://corrodinggames.com/rusted_warfare" target="_blank" rel="noopener">Corroding Games ↗</a> · <a href="https://play.google.com/store/apps/details?id=com.corrodinggames.rts" target="_blank" rel="noopener">Google Play ↗</a> · <a href="#downloads">${en?'Downloads':'下载资料'} ↗</a></p></article>`;}
function notFound(){main.innerHTML=heading('404 / UNKNOWN COORDINATES','这处坐标还没有内容。','链接可能已变化，回到工坊继续探索。')+'<div class="section-wrap"><a class="btn btn-dark" href="#home">返回首页 →</a></div>'}
function route(){RWEditor.dispose();window.RWStudio?.dispose();currentCode=null;const [page,id]=(location.hash.slice(1)||'home').split('/');document.body.dataset.page=page;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='code'&&a.dataset.nav==='library')||(page==='learn'&&a.dataset.nav==='tutorials')||(['unit-editor','map-editor','unit-art','map-art','ai-art'].includes(page)&&a.dataset.nav==='editors')));const titles={home:'把想象，写进战场',library:'代码仓库',tutorials:'模组教程',reference:'完整参数速查',downloads:'资料下载',manual:'中文手册',saved:'我的收藏',about:'关于本站',editors:'创作工具','unit-editor':'单位模组编辑器','map-editor':'地图与触发器','unit-art':'单位图片编辑器','map-art':'地图图片编辑器','ai-art':'AI 图形编辑器','ai-help':'模组帮助 AI',settings:'工坊设置'};document.title=(titles[page]||SNIPPETS.find(s=>s.id===id)?.title||LESSONS.find(l=>l.id===id)?.title||'工坊')+' · 铁锈战争模组工坊';if(['editors','unit-editor','map-editor'].includes(page))RWEditor.mount(page);else if(page==='home')homePage();else if(page==='library')libraryPage();else if(page==='saved')libraryPage(true);else if(page==='code')codePage(id);else if(page==='tutorials')RWAcademy.mount();else if(page==='legacy-tutorials')tutorialsPage();else if(page==='learn'){if(id?.startsWith('academy-'))RWAcademy.mount(id);else lessonPage(id);}else if(['unit-art','map-art'].includes(page))RWStudio.mount(page);else if(['ai-art','ai-help','settings'].includes(page))RWAI.mount(page);else if(page==='reference')referencePage();else if(page==='downloads')downloadsPage();else if(page==='manual')manualPage(id);else if(page==='about')aboutPage();else notFound();if(['home','tutorials'].includes(page)){const banner=document.createElement('section');banner.className='ed-home-banner';banner.innerHTML='<div><h2>让代码，变成看得见的创造。</h2><p>中文模块、动作积木与地图触发器，现已加入铁锈战争模组工坊。</p></div><div><a class="btn btn-dark" href="#unit-editor">单位模组编辑器 →</a><a class="btn btn-plain" href="#map-editor">地图与触发器 →</a></div>';const anchor=main.querySelector('.section-wrap');if(anchor)anchor.before(banner);else main.append(banner);}window.scrollTo(0,0)}
function download(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制，可粘贴到你的编辑器')}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'已复制':'浏览器限制了复制，请使用下载文件')}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;if(action==='category'){category=b.dataset.category;updateCards()}else if(action==='reset-search'){query='';category='全部代码';$('#code-search').value='';updateCards()}else if(action==='bookmark'){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];writeStore('rwlab-saved',saved);if(currentCode)codePage(currentCode.id);else updateCards();toast(saved.includes(id)?'已加入本地收藏':'已取消收藏')}else if(action==='copy-code'&&currentCode)copy(currentCode.code);else if(action==='download-code'&&currentCode)download(currentCode.code,currentCode.file);else if(action==='share-link')copy(location.href);else if(action==='complete-lesson'){completed=completed.includes(id)?completed.filter(x=>x!==id):[...completed,id];writeStore('rwlab-completed',completed);b.textContent=completed.includes(id)?'✓ 已标记完成':'✓ 标记本课完成';b.classList.toggle('completed',completed.includes(id));b.classList.toggle('btn-dark',!completed.includes(id))}else if(action==='ref-group'){refGroup=b.dataset.group;refScope='';refQuery='';refEvidence='';refPage=1;referencePage()}else if(action==='ref-prev'||action==='ref-next'){refPage+=action==='ref-prev'?-1:1;updateReference();$('#reference-results').scrollIntoView({block:'start',behavior:'smooth'})}else if(action==='ref-reset'){refScope='';refQuery='';refEvidence='';refPage=1;referencePage()}else if(action==='contribute'){const draft=readStore('rwlab-draft',{});for(const [name,value]of Object.entries(draft)){const field=$('#contribute-form').elements.namedItem(name);if(field)field.value=value}$('#contribute-dialog').showModal()}else if(action==='close-dialog')$('#contribute-dialog').close();else if(action==='save-draft'){const value=Object.fromEntries(new FormData($('#contribute-form')));if(writeStore('rwlab-draft',value))toast('草稿已保存在当前浏览器')}});
document.addEventListener('input',e=>{if(e.target.id==='code-search'){query=e.target.value;updateCards()}else if(e.target.id==='ref-search'){refQuery=e.target.value;refPage=1;updateReference()}});
document.addEventListener('change',e=>{if(e.target.id==='code-sort'){order=e.target.value;updateCards()}else if(e.target.id==='ref-scope'){refScope=e.target.value;refPage=1;updateReference()}else if(e.target.id==='ref-evidence'){refEvidence=e.target.value;refPage=1;updateReference()}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('#contribute-dialog').open){const input=$('#code-search')||$('#ref-search');if(input){e.preventDefault();input.focus()}}});
$('#contribute-form').addEventListener('submit',e=>{e.preventDefault();const value=Object.fromEntries(new FormData(e.target));writeStore('rwlab-draft',value);download(JSON.stringify({...value,target_version:'请按实际填写',validation:'作者需注明静态检查 / 实机验证情况',exported_at:new Date().toISOString()},null,2),'rwlab-share-card.json','application/json');toast('分享卡片已导出，可发送给朋友或站长')});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'})});
window.addEventListener('hashchange',route);route();
